// ciphertext for an 8-byte plaintext is 8 bytes -> 11 base64url chars, no padding.
// 11 chars carry 66 bits but only 64 are data: the last char has 2 unused low bits.
let sameBytes = 0, lastCharA = 0, N = 20000;
